package kr.campusrent;
import java.time.*;import java.util.*;import javax.servlet.http.*;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class OperationalTest {
 @Test void throttleNormalizesAccountsAndKeepsLimitAcrossAddresses(){LoginThrottle t=new LoginThrottle(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC),2,10,1000);t.attempt("Test@Example.com","a");t.attempt(" test@example.com ","b");assertThrows(LoginThrottle.Limited.class,()->t.attempt("test@example.com","c"));}
 @Test void throttleLimitsAddressAcrossAccounts(){LoginThrottle t=new LoginThrottle(Clock.systemUTC(),10,2,1000);t.attempt("a","ip");t.attempt("b","ip");assertThrows(LoginThrottle.Limited.class,()->t.attempt("c","ip"));}
 @Test void throttleWindowExpires(){final long[] now={0};Clock c=mock(Clock.class);when(c.millis()).thenAnswer(i->now[0]);LoginThrottle t=new LoginThrottle(c,1,1,1000);t.attempt("a","ip");now[0]=1000;t.attempt("a","ip");}
 @Test void passwordChangeRevokesOnlySameUserSessions(){AuthSessions r=new AuthSessions();MockHttpSession first=new MockHttpSession(),second=new MockHttpSession(),other=new MockHttpSession();first.setAttribute("user",RentalService.obj("id","1"));second.setAttribute("user",RentalService.obj("id","1"));other.setAttribute("user",RentalService.obj("id","2"));r.track(first);r.track(second);r.track(other);r.invalidateUser("1");assertTrue(first.isInvalid());assertTrue(second.isInvalid());assertFalse(other.isInvalid());}
 @Test void databaseErrorHidesDetailsAndDistinguishesConflict(){OperationalErrors errors=new OperationalErrors();MockHttpServletRequest request=new MockHttpServletRequest("POST","/api/requests");assertEquals(503,errors.database(new org.springframework.dao.DataAccessResourceFailureException("secret JDBC URL"),request).getStatusCodeValue());assertEquals(409,errors.database(new org.springframework.dao.DuplicateKeyException("private value"),request).getStatusCodeValue());assertFalse(errors.database(new org.springframework.dao.QueryTimeoutException("private SQL"),request).getBody().toString().contains("private"));}
 @Test void readinessFailureDoesNotBreakLiveness(){JdbcTemplate db=mock(JdbcTemplate.class);when(db.queryForObject("SELECT 1 FROM DUAL",Integer.class)).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("hidden"));OperationalController c=new OperationalController(db);assertEquals(503,c.ready().getStatusCodeValue());assertEquals("UP",((Map<?,?>)c.live()).get("status"));}
 @Test void connectionLossDuringSecondWriteRollsBack()throws Exception{javax.sql.DataSource ds=mock(javax.sql.DataSource.class);java.sql.Connection connection=mock(java.sql.Connection.class);java.sql.Statement statement=mock(java.sql.Statement.class);when(ds.getConnection()).thenReturn(connection);when(connection.getAutoCommit()).thenReturn(true);when(connection.createStatement()).thenReturn(statement);when(statement.executeUpdate("INSERT first")).thenReturn(1);when(statement.executeUpdate("INSERT second")).thenThrow(new java.sql.SQLRecoverableException("simulated connection loss"));JdbcTemplate db=new JdbcTemplate(ds);TransactionTemplate tx=new TransactionTemplate(new DataSourceTransactionManager(ds));assertThrows(RuntimeException.class,()->tx.execute(s->{db.update("INSERT first");db.update("INSERT second");return null;}));verify(connection).rollback();verify(connection,never()).commit();}
 @Test void productionFailsWithoutRequiredControls(){org.springframework.mock.env.MockEnvironment env=new org.springframework.mock.env.MockEnvironment();assertThrows(IllegalStateException.class,()->new ProductionGuard(env).run(null));env.setProperty("campusrent.auth.block-demo-accounts","true");env.setProperty("server.servlet.session.cookie.secure","true");env.setProperty("server.address","127.0.0.1");assertDoesNotThrow(()->new ProductionGuard(env).run(null));}
 @Test void loginLimitReturns429WithRetryHeader()throws Exception{RentalService service=mock(RentalService.class);when(service.login(any())).thenThrow(new IllegalArgumentException("이메일 또는 비밀번호를 확인해주세요."));ApiController c=new ApiController(service,mock(AdminService.class),mock(ModelService.class));c.throttle=new LoginThrottle(Clock.systemUTC(),1,10,900000);c.sessions=new AuthSessions();org.springframework.test.web.servlet.MockMvc http=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(c).build();org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request=org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/login").contentType("application/json").content("{\"email\":\"limit@example.com\",\"password\":\"wrong\"}");http.perform(request).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());http.perform(request).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isTooManyRequests()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().string("Retry-After","900"));}
}
